<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { ElMessage, ElMessageBox } from 'element-plus';
import { apiClient } from '../../utils/api.js';
import { uploadListingMedia } from '../../api/tools/imageCropper.js';
import WorkflowMaterialInput from '../../components/listing/WorkflowMaterialInput.vue';
import WorkflowRunReview from '../../components/listing/WorkflowRunReview.vue';
import { WORKFLOW_TYPES, createWorkflowNode, keyCaseWorkflow, validateWorkflow, validateWorkflowVariants } from '../../../../src/shared/product-workflow.js';
import { isWorkflowInput, workflowDefault, expandWorkflowVariants } from '../../../../src/shared/product-workflow-inputs.js';

const router=useRouter(),tab=ref('library'),templates=ref([]),runs=ref([]),jobs=ref([]),listingTemplates=ref([]);
const templateDocument=ref(null),definition=ref(blankWorkflow()),selectedId=ref(''),categoryId=ref(null);
const busy=ref(false),busyLabel=ref(''),importInput=ref(null),dragged=ref(null),productionOpen=ref(false);
const sharedValues=ref({}),variants=ref([]),runDocument=ref(null),reviewEditing=ref(false),expandedVariant=ref('');
let pollTimer,polling=false;
const clone=value=>JSON.parse(JSON.stringify(value));
const selected=computed(()=>definition.value.nodes.find(n=>n.id===selectedId.value));
const inputs=computed(()=>definition.value.nodes.filter(isWorkflowInput));
const sharedInputs=computed(()=>inputs.value.filter(n=>n.scope==='shared'));
const variantInputs=computed(()=>inputs.value.filter(n=>n.scope!=='shared'));
const category=computed(()=>definition.value.category||{});
const categoryAttributes=computed(()=>category.value.attributes||[]);
const editableNodes=computed(()=>definition.value.nodes.filter(n=>n.type!=='listing'));
const earlierNodes=computed(()=>definition.value.nodes.slice(0,definition.value.nodes.findIndex(n=>n.id===selectedId.value)).filter(n=>['field','attribute','images','image','approval','copy'].includes(n.type)));
const executableNodes=computed(()=>definition.value.nodes.filter(n=>['image','copy'].includes(n.type)));
const stateFor=id=>jobs.value.find(j=>j.run_id===id)||{};
const statusLabels={queued:'排队中',running:'后台生成中',awaiting_review:'待人工检查',ready:'检查完成',failed:'失败待处理',imported:'生产完成'};
const taskRows=computed(()=>runs.value.filter(r=>!r.draft_id));
const resultRows=computed(()=>runs.value.filter(r=>r.draft_id));
const currentJob=computed(()=>runDocument.value?.payload.draftId?{status:'imported'}:stateFor(runDocument.value?.id));
function blankWorkflow(){return {schemaVersion:1,name:'新产品流程',globalPrompt:'保持真实产品外观，套图风格一致，只使用已确认事实。',nodes:[]};}
async function action(work){if(busy.value)return;busy.value=true;try{await work();}catch(error){ElMessage.error(error.message||'操作失败');}finally{busy.value=false;busyLabel.value='';}}
async function refreshLists(){const values=await Promise.all([apiClient.get('/api/product-workflows/templates',{noCache:true}),apiClient.get('/api/product-workflows/runs',{noCache:true}),apiClient.get('/api/product-workflows/job-states',{noCache:true})]);[templates.value,runs.value,jobs.value]=values;}
onMounted(()=>{action(async()=>{await refreshLists();listingTemplates.value=await apiClient.get('/api/listing/templates');});pollTimer=setInterval(poll,4000);});
onUnmounted(()=>clearInterval(pollTimer));
async function poll(){if(polling||busy.value||reviewEditing.value||!['tasks','results'].includes(tab.value))return;polling=true;try{await refreshLists();if(runDocument.value)runDocument.value=await apiClient.get(`/api/product-workflows/runs?id=${encodeURIComponent(runDocument.value.id)}`,{noCache:true});}catch{/* Explicit refresh reports failures; retain the last visible state on transient network errors. */}finally{polling=false;}}
function resetMaterials(){sharedValues.value=Object.fromEntries(sharedInputs.value.map(n=>[n.id,workflowDefault(n)]));variants.value=[freshVariant(0)];}
function freshVariant(index){return {id:`v_${crypto.randomUUID().replaceAll('-','')}`,label:`变体 ${index+1}`,values:Object.fromEntries(variantInputs.value.map(n=>[n.id,workflowDefault(n)])),promptOverrides:{}};}
function addVariant(){if(variants.value.length>=20)return ElMessage.warning('最多 20 个变体');variants.value.push(freshVariant(variants.value.length));}
function newTemplate(){templateDocument.value=null;definition.value=blankWorkflow();selectedId.value='';categoryId.value=null;tab.value='engineer';}
async function loadTemplate(id){const doc=await apiClient.get(`/api/product-workflows/templates?id=${encodeURIComponent(id)}`,{noCache:true});templateDocument.value=doc;definition.value=clone(doc.payload);categoryId.value=definition.value.nodes.find(n=>n.type==='listing')?.templateId||null;selectedId.value=editableNodes.value[0]?.id;}
async function editTemplate(id){await action(async()=>{await loadTemplate(id);tab.value='engineer';});}
async function useTemplate(id){await action(async()=>{await loadTemplate(id);if(!category.value.templateId)await attachCategory();resetMaterials();productionOpen.value=true;});}
function basicWorkflow(){const name={...createWorkflowNode('field','name'),scope:'shared',label:'产品名称'};const product={...createWorkflowNode('images','product'),label:'变体产品主图'};const style={...createWorkflowNode('images','style'),scope:'shared',referenceRole:'style',label:'通用视觉参考',required:false};const main={...createWorkflowNode('image','main'),role:'main',label:'主图',inputs:['name','product','style']};const approval={...createWorkflowNode('approval','approve'),label:'确认主图',inputs:['main']};const detail={...createWorkflowNode('image','detail_1'),label:'详情图 1',inputs:['name','product','approve']};const copy={...createWorkflowNode('copy','copy'),inputs:['name']};return [createWorkflowNode('listing','listing'),name,product,style,main,approval,detail,copy];}
async function attachCategory(){if(!categoryId.value)throw new Error('请先选择现有上架类目模板');const imported=await apiClient.get(`/api/product-workflows/category?id=${categoryId.value}`,{noCache:true});const oldAttrs=new Set(definition.value.nodes.filter(n=>n.type==='attribute').map(n=>n.id));if(!definition.value.nodes.length)definition.value.nodes=basicWorkflow();definition.value.nodes=definition.value.nodes.filter(n=>!oldAttrs.has(n.id));for(const node of definition.value.nodes)node.inputs=node.inputs.filter(id=>!oldAttrs.has(id));let listing=definition.value.nodes.find(n=>n.type==='listing');if(!listing){listing=createWorkflowNode('listing','listing');definition.value.nodes.unshift(listing);}listing.templateId=Number(categoryId.value);definition.value.category=imported;for(const attr of imported.attributes.filter(n=>n.required&&![4191,23171].includes(n.attributeId)))addAttribute(attr);selectedId.value=editableNodes.value[0]?.id;ElMessage.success('类目模板已导入，必填属性已加入流程；可设置公共值或交给运营逐变体填写');}
function insertInput(node){const first=definition.value.nodes.findIndex(n=>['image','copy','approval'].includes(n.type));definition.value.nodes.splice(first<0?definition.value.nodes.length:first,0,node);for(const target of definition.value.nodes.filter(n=>['image','copy'].includes(n.type)))if(!target.inputs.includes(node.id))target.inputs.push(node.id);selectedId.value=node.id;}
function addAttribute(attr){if(!attr)return;const existing=definition.value.nodes.find(n=>n.type==='attribute'&&Number(n.attributeId)===Number(attr.attributeId));if(existing){selectedId.value=existing.id;return;}const node=clone(attr);const field=definition.value.nodes.find(n=>n.type==='field'&&n.label===node.label);if(field){node.scope=field.scope;for(const target of definition.value.nodes)target.inputs=target.inputs.map(id=>id===field.id?node.id:id);definition.value.nodes=definition.value.nodes.filter(n=>n.id!==field.id);}insertInput(node);}
function addNode(type,index=definition.value.nodes.length){if(type==='attribute'||type==='listing')return;const node=createWorkflowNode(type);if(isWorkflowInput(node)){insertInput(node);return;}if(['image','copy'].includes(type))node.inputs=definition.value.nodes.slice(0,index).filter(n=>isWorkflowInput(n)||n.type==='approval').map(n=>n.id);definition.value.nodes.splice(index,0,node);selectedId.value=node.id;}
function beginDrag(event,kind,value){dragged.value={kind,value};event.dataTransfer.setData('text/plain',String(value));event.dataTransfer.effectAllowed=kind==='node'?'move':'copy';}
function dropNode(event,index){event.preventDefault();const drag=dragged.value;dragged.value=null;if(!drag)return;if(drag.kind==='attribute')return addAttribute(categoryAttributes.value.find(a=>a.id===drag.value));if(drag.kind==='type')return addNode(drag.value,index);const previous=definition.value.nodes.findIndex(n=>n.id===drag.value);if(previous<1)return;const nodes=clone(definition.value.nodes),[moved]=nodes.splice(previous,1);nodes.splice(previous<index?index-1:index,0,moved);const seen=new Set();if(nodes.some(n=>{const bad=n.inputs.some(id=>!seen.has(id));seen.add(n.id);return bad;}))return ElMessage.warning('该顺序会引用后面的节点，请先修改输入引用');definition.value.nodes=nodes;}
function removeNode(){const n=selected.value;if(!n)return;if(definition.value.nodes.some(x=>x.inputs.includes(n.id)))return ElMessage.warning('先从引用它的节点中移除输入引用');definition.value.nodes=definition.value.nodes.filter(x=>x.id!==n.id);selectedId.value=editableNodes.value[0]?.id;}
function duplicateNode(){if(selected.value.type==='attribute')return ElMessage.info('同一类目属性只配置一次，可设置为公共或变体填写');const n=clone(selected.value);n.id=createWorkflowNode(n.type).id;n.label+=' 副本';definition.value.nodes.splice(definition.value.nodes.findIndex(x=>x.id===selectedId.value)+1,0,n);selectedId.value=n.id;}
function slotCountChanged(){const n=selected.value;n.slots=Array.from({length:n.count},(_,i)=>n.slots[i]||`第 ${i+1} 张参考用途`);}
async function saveTemplate(){await action(async()=>{if(!category.value.templateId)throw new Error('第一步请先导入上架类目模板');const payload=validateWorkflow(definition.value);templateDocument.value=await apiClient.post('/api/product-workflows/templates',{id:templateDocument.value?.id,revision:templateDocument.value?.revision,payload});await refreshLists();ElMessage.success('流程已保存，可在已有流程中使用');});}
async function loadExample(){await action(async()=>{if(!category.value.templateId)throw new Error('请先导入本企业的类目模板');const savedCategory=clone(category.value);definition.value=keyCaseWorkflow();definition.value.nodes.find(n=>n.type==='listing').templateId=savedCategory.templateId;definition.value.category=savedCategory;for(const attr of savedCategory.attributes.filter(n=>n.required&&![4191,23171].includes(n.attributeId)))addAttribute(attr);selectedId.value='main';});}
function exportTemplate(){try{const payload=validateWorkflow(definition.value);const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}));const link=window.document.createElement('a');link.href=url;link.download=`${payload.name.replace(/[\\/:*?"<>|]/g,'-')}.workflow.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){ElMessage.error(error.message);}}
async function importTemplate(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;await action(async()=>{if(file.size>1024*1024)throw new Error('模板文件最多 1 MB');definition.value=validateWorkflow(JSON.parse(await file.text()));templateDocument.value=null;categoryId.value=null;delete definition.value.category;const listing=definition.value.nodes.find(n=>n.type==='listing');listing.templateId=0;selectedId.value=editableNodes.value[0]?.id;tab.value='engineer';ElMessage.info('文件已导入，请先重新绑定本企业的上架类目模板');});}
async function upload(file,target,node,index){if(!file)return;await action(async()=>{busyLabel.value='上传产品材料';const result=await uploadListingMedia(file,{source_module:'product_workflow',role:node.referenceRole||'product'});const url=result.publishUrl||result.url||result.previewUrl;if(!url)throw new Error('上传没有返回图片地址');target[node.id][index]=url;});}
async function submitProduction(){await action(async()=>{const snapshot=validateWorkflow(definition.value);const expanded=expandWorkflowVariants(snapshot,variants.value,sharedValues.value);validateWorkflowVariants(snapshot,expanded);runDocument.value=await apiClient.post('/api/product-workflows/runs',{payload:{definition:snapshot,templateId:templateDocument.value?.id||null,templateRevision:templateDocument.value?.revision||null,variants:clone(variants.value),sharedValues:clone(sharedValues.value),outputs:{},draftId:null}});productionOpen.value=false;tab.value='tasks';await refreshLists();ElMessage.success('已提交后台生产，可以关闭页面；需要人工检查时会显示在任务列表');});}
async function openRun(id,completed=false){await action(async()=>{runDocument.value=await apiClient.get(`/api/product-workflows/runs?id=${encodeURIComponent(id)}`,{noCache:true});tab.value=completed?'results':'tasks';});}
async function runAction(body){await action(async()=>{if(body.action==='retry'&&runDocument.value.payload.outputs[body.variantId]?.[body.nodeId]?.status!=='unknown'){try{await ElMessageBox.confirm('重生成会清除依赖本节点的后续结果，并重新调用 AI。是否继续？','重生成',{type:'warning'});}catch{return;}}runDocument.value=await apiClient.post('/api/product-workflows/run-action',body);await refreshLists();});}
async function finishProduction(){await action(async()=>{try{await ElMessageBox.confirm('我已检查全部变体的套图、文案和属性，确认完成生产并生成上架草稿。','整套人工检查',{confirmButtonText:'确认完成',type:'info'});}catch{return;}if(runDocument.value.payload.draftImportStatus!=='unknown')runDocument.value=await apiClient.post('/api/product-workflows/run-action',{id:runDocument.value.id,action:'approve-all'});try{await apiClient.post('/api/product-workflows/import-draft',{id:runDocument.value.id});}finally{runDocument.value=await apiClient.get(`/api/product-workflows/runs?id=${encodeURIComponent(runDocument.value.id)}`,{noCache:true});await refreshLists();}tab.value='results';ElMessage.success('生产完成，已生成操作箱草稿；可预览编辑并选择店铺上架');});}
function openDraft(id){router.push({path:'/listing-automation',query:{draftId:id}});}
watch(tab,()=>{reviewEditing.value=false;});
</script>

<template>
  <div class="workflow-page" v-loading="busy" :element-loading-text="busyLabel||'正在保存'">
    <header class="page-heading"><div><h2>产品模板工作流</h2><p>先定类目，再配置变体与套图规则；提交后台生产，人工检查后上架。</p></div><el-tag effect="plain">流程可复用 · 支持多变体</el-tag></header>
    <el-tabs v-model="tab">
      <el-tab-pane label="已有流程" name="library">
        <div class="toolbar"><h3>选择流程开始生产</h3><el-button type="primary" @click="newTemplate">新建一个流程</el-button><el-button @click="importInput.click()">导入流程文件</el-button></div>
        <el-empty v-if="!templates.length" description="还没有产品流程，先导入类目模板创建第一个流程"><el-button type="primary" @click="newTemplate">创建第一个流程</el-button></el-empty>
        <div class="flow-library"><article v-for="item in templates" :key="item.id" class="flow-card"><div class="toolbar"><h3>{{ item.name }}</h3><el-tag>v{{ item.revision }}</el-tag></div><p>{{ item.category_name||'已保存的品类工作流' }}</p><p>共用参考与分镜规则 · 每个变体独立产品图</p><div class="toolbar"><el-button type="primary" @click="useTemplate(item.id)">使用流程生产</el-button><el-button @click="editTemplate(item.id)">编辑流程</el-button></div></article></div>
      </el-tab-pane>
      <el-tab-pane label="新建／编辑流程" name="engineer">
        <section class="category-first"><div><h3>第一步 · 导入上架类目模板</h3><p>沿用操作箱已有类目与属性定义，工程师选择哪些属性固定、共用或交给运营填写。</p></div><div class="toolbar"><el-select v-model="categoryId" filterable placeholder="选择现有上架类目模板"><el-option v-for="item in listingTemplates" :key="item.id" :label="item.template_name||item.category_name" :value="Number(item.id)"/></el-select><el-button type="primary" :disabled="!categoryId" @click="action(attachCategory)">{{ category.templateId?'重新导入类目':'导入类目模板' }}</el-button></div><el-tag v-if="category.templateId" type="success">已绑定：{{ category.categoryName||category.name }}</el-tag></section>
        <template v-if="category.templateId">
          <div class="toolbar"><h3>第二步 · 配置属性、图片与生成流程</h3><el-button @click="loadExample">套用钥匙壳分镜</el-button><el-button @click="exportTemplate">导出 JSON</el-button><el-button type="primary" @click="saveTemplate">保存流程</el-button><el-button @click="resetMaterials();productionOpen=true">试用当前流程</el-button></div>
          <div class="workflow-meta"><el-input v-model="definition.name" placeholder="流程名称"/><el-input v-model="definition.globalPrompt" type="textarea" :rows="2" placeholder="全局提示词：统一风格、语言和产品保真要求"/></div>
          <div class="workflow-editor"><aside class="workflow-palette"><h3>类目属性</h3><p>拖出需要预设或填写的属性</p><button v-for="attr in categoryAttributes" :key="attr.id" draggable="true" @dragstart="beginDrag($event,'attribute',attr.id)" @click="addAttribute(attr)">{{ attr.label }} <em v-if="attr.required">必填</em></button><h3>流程节点</h3><template v-for="(name,type) in WORKFLOW_TYPES" :key="type"><button v-if="!['attribute','listing'].includes(type)" draggable="true" @dragstart="beginDrag($event,'type',type)" @click="addNode(type)">{{ name }} ＋</button></template></aside>
            <div class="workflow-canvas" @dragover.prevent @drop="dropNode($event,definition.nodes.length)"><div class="category-root"><strong>上架类目模板</strong><small>{{ category.categoryName||category.name }}</small></div><div v-for="node in editableNodes" :key="node.id" class="workflow-node-wrap" @dragover.prevent.stop @drop.stop="dropNode($event,definition.nodes.findIndex(n=>n.id===node.id))"><span class="workflow-arrow">↓</span><button class="workflow-node" :class="{selected:selectedId===node.id}" draggable="true" @dragstart.stop="beginDrag($event,'node',node.id)" @click="selectedId=node.id"><span><strong>{{ node.label }}</strong><small>{{ WORKFLOW_TYPES[node.type] }}<template v-if="isWorkflowInput(node)"> · {{ node.scope==='shared'?'商品共用':'逐变体填写' }}</template></small></span><span>⋮⋮</span></button></div></div>
            <aside v-if="selected" class="workflow-inspector"><div class="toolbar"><h3>节点设置</h3><el-tag>{{ WORKFLOW_TYPES[selected.type] }}</el-tag></div><label>节点名称<el-input v-model="selected.label"/></label>
              <template v-if="isWorkflowInput(selected)"><label>填写范围<el-select v-model="selected.scope"><el-option label="商品公共资料（只填一次）" value="shared"/><el-option label="每个变体分别填写" value="variant"/></el-select></label><el-checkbox v-model="selected.required">必须填写</el-checkbox></template>
              <template v-if="['field','attribute'].includes(selected.type)"><label>工程师预设默认值<WorkflowMaterialInput v-model="selected.defaultValue" :node="selected" :category="category" @options="selected.options=$event"/></label><label>填写说明<el-input v-model="selected.help"/></label><p v-if="selected.type==='attribute'">绑定类目属性：{{ selected.attributeId }}，只会将选定值写入上架属性。</p></template>
              <template v-if="selected.type==='images'"><label>用途<el-select v-model="selected.referenceRole"><el-option label="真实产品外观" value="product"/><el-option label="共同适配对象" value="compatibility"/><el-option label="仅视觉风格" value="style"/></el-select></label><label>要求图片数<el-input-number v-model="selected.count" :min="1" :max="8" @change="slotCountChanged"/></label><label v-for="(_,i) in selected.slots" :key="i">第 {{ i+1 }} 张用途<el-input v-model="selected.slots[i]"/></label></template>
              <label v-if="['image','copy','approval'].includes(selected.type)">引用前序输入<el-select v-model="selected.inputs" multiple><el-option v-for="n in earlierNodes" :key="n.id" :label="n.label" :value="n.id"/></el-select></label>
              <template v-if="selected.type==='image'"><label>图片位置<el-select v-model="selected.role"><el-option label="主图" value="main"/><el-option label="详情图" value="detail"/></el-select></label><label>比例<el-select v-model="selected.ratio"><el-option v-for="ratio in ['3:4','1:1','4:5']" :key="ratio" :label="ratio" :value="ratio"/></el-select></label></template>
              <label v-if="selected.type==='copy'">文案输出<el-select v-model="selected.target"><el-option label="标题、标签、描述整组" value="bundle"/><el-option label="仅标题" value="title"/><el-option label="仅标签" value="tags"/><el-option label="仅描述" value="description"/></el-select></label>
              <label v-if="['image','copy'].includes(selected.type)">所有变体共用的节点提示词<el-input v-model="selected.prompt" type="textarea" :rows="6"/></label>
              <label v-if="selected.type==='price'">售价（RUB）<el-input-number v-model="selected.value" :min="0.01" :precision="2"/></label><template v-if="selected.type==='package'"><label>包装重量（g）<el-input-number v-model="selected.weight" :min="0.1"/></label><label v-for="(name,key) in {length:'长',width:'宽',height:'高'}" :key="key">{{ name }}（cm）<el-input-number v-model="selected[key]" :min="0.1"/></label></template>
              <div class="toolbar"><el-button @click="duplicateNode">复制节点</el-button><el-button type="danger" plain @click="removeNode">删除</el-button></div>
            </aside>
          </div>
        </template>
      </el-tab-pane>
      <el-tab-pane :label="`生产任务／待人工检查${taskRows.length?' · '+taskRows.length:''}`" name="tasks">
        <div class="toolbar"><h3>后台生产与人工检查</h3><el-button @click="action(refreshLists)">刷新任务</el-button></div>
        <el-table :data="taskRows" empty-text="暂无生产任务，从已有流程开始生产"><el-table-column prop="name" label="流程" min-width="180"/><el-table-column label="变体" width="80"><template #default="{row}">{{ row.variant_count||'—' }}</template></el-table-column><el-table-column label="状态" min-width="150"><template #default="{row}"><el-tag :type="stateFor(row.id).status==='failed'?'danger':stateFor(row.id).status==='awaiting_review'?'warning':'info'">{{ statusLabels[stateFor(row.id).status]||'待提交后台' }}</el-tag></template></el-table-column><el-table-column label="操作" min-width="200"><template #default="{row}"><el-button type="primary" text @click="openRun(row.id)">{{ stateFor(row.id).status==='awaiting_review'?'进入人工预览':'查看进度／处理' }}</el-button></template></el-table-column></el-table>
        <section v-if="runDocument&&!runDocument.payload.draftId" class="run-detail"><div class="toolbar"><el-button v-if="!stateFor(runDocument.id).status" @click="runAction({id:runDocument.id,action:'start'})">提交后台执行</el-button><el-tag>{{ statusLabels[currentJob.status]||'等待后台执行' }}</el-tag></div><WorkflowRunReview :record="runDocument" :job="currentJob" :busy="busy" @action="runAction" @finish="finishProduction" @open-draft="openDraft" @editing="reviewEditing=$event"/></section>
      </el-tab-pane>
      <el-tab-pane label="生产结果" name="results">
        <div class="toolbar"><h3>已完成的商品</h3><el-button @click="action(refreshLists)">刷新结果</el-button></div>
        <el-table :data="resultRows" empty-text="人工检查通过并完成生产后，商品会出现在这里"><el-table-column prop="name" label="流程" min-width="180"/><el-table-column label="状态" min-width="150"><template #default>已生成操作箱草稿</template></el-table-column><el-table-column label="操作" min-width="230"><template #default="{row}"><el-button text @click="openRun(row.id,true)">查看完整产出</el-button><el-button type="primary" @click="openDraft(row.draft_id)">预览并上架</el-button></template></el-table-column></el-table>
        <section v-if="runDocument?.payload.draftId" class="run-detail"><WorkflowRunReview :record="runDocument" :job="currentJob" @open-draft="openDraft"/></section>
      </el-tab-pane>
    </el-tabs>
    <input ref="importInput" type="file" accept=".json" hidden @change="importTemplate"/>
    <el-dialog v-model="productionOpen" :title="`使用流程：${definition.name}`" width="1160px" class="production-dialog" :close-on-click-modal="false">
      <template v-if="productionOpen"><el-steps :active="1" simple><el-step title="已绑定类目"/><el-step title="公共资料与变体"/><el-step title="后台生成"/><el-step title="人工预览与上架"/></el-steps><p class="category-summary">上架类目：{{ category.categoryName||category.name }} · 默认一个变体，可快速添加多个</p>
        <h3>商品公共资料 · 只填写一次</h3><div class="common-inputs"><label v-for="node in sharedInputs" :key="node.id">{{ node.label }} <em v-if="node.required">必填</em><WorkflowMaterialInput v-model="sharedValues[node.id]" :node="node" :category="category" @options="node.options=$event" @upload="(file,index)=>upload(file,sharedValues,node,index)"/></label></div>
        <div class="toolbar"><h3>变体资料</h3><el-button @click="addVariant">＋ 添加变体</el-button><el-tag>{{ variants.length===1?'单变体':variants.length+' 个变体' }}</el-tag></div>
        <el-table :data="variants" border><el-table-column label="变体" width="170" fixed><template #default="{row}"><el-input v-model="row.label" placeholder="变体名称"/></template></el-table-column><el-table-column v-for="node in variantInputs" :key="node.id" :label="node.label+(node.required?' *':'')" :width="node.type==='images'?240:190"><template #default="{row}"><WorkflowMaterialInput v-model="row.values[node.id]" :node="node" :category="category" @options="node.options=$event" @upload="(file,index)=>upload(file,row.values,node,index)"/></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row,$index}"><el-button v-if="variants.length>1" text type="danger" @click="variants.splice($index,1)">删除</el-button><el-button text @click="expandedVariant=expandedVariant===row.id?'':row.id">特殊要求</el-button></template></el-table-column></el-table>
        <section v-for="variant in variants.filter(v=>v.id===expandedVariant)" :key="variant.id" class="variant-overrides"><h4>{{ variant.label }} · 可选的分镜补充要求</h4><p>留空即遵循模板。这里只补充该变体的差异要求，不修改共用模板。</p><label v-for="node in executableNodes" :key="node.id">{{ node.label }}<el-input v-model="variant.promptOverrides[node.id]" type="textarea" :rows="2" placeholder="可选，例如该变体需要额外突出红色包边"/></label></section>
        <p>提交后后台自动执行，可以离开页面。主图需要确认时暂停，确认后自动继续；最终整套检查完成再生成上架草稿。</p>
      </template><template #footer><el-button @click="productionOpen=false">稍后提交</el-button><el-button type="primary" :loading="busy" @click="submitProduction">提交后台生产</el-button></template>
    </el-dialog>
  </div>
</template>
